def inventory(base):
 manifest=json.loads((HERE/'candidate-manifest.json').read_text());changed={x['path'] for x in manifest['changed_files']}
 windows=[]
 for file in sorted((base/'unified').glob('*.xml')):
  path='unified/'+file.name;candidate=HERE/'skin-delta'/path
  root=E.parse(candidate if candidate.exists() else file).getroot()
  if root.tag!='window':continue
  windows.append({'path':path,'changed':path in changed,'xml_parsed':True,'action_controls':sum(bool(c.findall('onclick')) for c in root.findall('.//control')),'runtime_walkthrough':'NOT_RUN'})
 data={'baseline':manifest['authoritative_parent'],'candidate':manifest['candidate'],'branch':'work/infinity-ui-stabilization-2103365','protected_repo_parent':'faf41ee1d35fe55140bb1e193089643cc9ac06ee',
 'repairs':[dict(zip(['id','screen','owner','defect','implemented_behavior','evidence','status'],row)) for row in REPAIRS],
 'source_window_inventory':windows,'source_window_count':len(windows),'active_xml_documents_parsed':manifest['active_xml_parsed'],
 'runtime_end_to_end_walkthrough_completed':False,'physical_fold_accepted':False,
 'additional_unverified_possibilities':['Provider may own a custom source dialog; installed call site unavailable.','Packed/legacy texture references without standalone files need runtime resolution before calling them missing.','Android insets, live-resize focus/touch restoration, loading truthfulness and foreground/idle transitions need physical runtime evidence.','UI stall/resource growth and backend delays cannot be diagnosed from XML geometry alone.'],
 'preserved_screen_families':['Choose Your Experience/Home/header/hero/widgets and artwork','Movie/TV poster views, episodes and detail data','Settings values/theme/view selections','Player overlays, native playback and PVR','Provider scraping/authentication/source ordering','Power/Close behavior and protected .204 delta','Command Center/Resume Hub identities, persistence and source hashes'],
 'runtime_limit':'No Kodi executable, physical Fold session or Android/device bridge in this environment; source checks/projections cannot prove runtime rendering or interaction.'}
 (HERE/'implementation-inventory.json').write_text(json.dumps(data,indent=2)+'\n');return data

