 body+=table(['Reference','Exact SHA256'],[['Candidate ZIP',m['candidate_sha256']],['Current .204 rollback ZIP',m['base_sha256']],['Protected .201 parent ZIP',m['protected_parent_sha256']],['Unchanged Power XML',m['power_sha256']]])+'</section>'
