 style='body{margin:0;background:#091018;color:#e6edf6;font:16px/1.55 system-ui}header{padding:56px max(24px,6vw);background:#101e2d;border-bottom:2px solid #24a8ff}header span{color:#24a8ff;font-size:13px;letter-spacing:2px}h1{font-size:40px;line-height:1.2}section{margin:32px auto;max-width:1250px;padding:0 24px}h2{color:#fff}p{max-width:1000px}a{color:#62c1ff}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;vertical-align:top;padding:12px;border:1px solid #26394b;overflow-wrap:anywhere}th{background:#142337}details{padding:14px;margin:18px 0;background:#111c29;border:1px solid #26394b;border-radius:8px}summary{cursor:pointer;color:#88d1ff}.pair,.gallery{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:12px 0}figcaption{font-size:13px;color:#b8c9d9;padding:8px}img{width:100%;height:auto;border:1px solid #29425a}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px} @media(max-width:700px){.pair,.gallery{grid-template-columns:1fr}h1{font-size:30px}}'
